数算的笔记/互联网开发/数据结构之线性表之链表及php代码实现.html.description:
上章的问题： 用户创建有序的课程： 课程1
课程2
课程3
课程4 按照一般做法，把这些课程信息存在一张课程表中，用一个字段比如 sort 用来标识当前课程的排序，取出的时候SQL ： order by sort ASC
遇到问题来了：在页面上显示的时候，允许用户拖动任一课程到任一位置，那么我们怎么改变表中的排序字段值能使拖动后的排序仍然正确显示在页面上 这个问题很容易遇到：因为惯性思维，order by sort ASC顺手就来了,所以在遇到拖动排序的需求时，问题就来了，虽然通过计算前后，后面排序全部更新来达到目的，但显然做的很不开心，觉得不应该是这个样子，如果你知道链表，那么就不存在问题了链表的存储结构单链表中的每个结点都包含一个“数据域”和一个“指针域”。“数据域”中包含当前结点的数据，“指针域”包含下一节点的存储地址，头指针head是指向开始结点的，结束结点没有后继结点，所以结束结点的指针域为空，即null。链表的常用操作
插入结点到表头
思路：将head头指针的next指针给新增结点的next，然后将整个新增结点给head头指针的next
插入结点到表尾
思路：插入方法与插入到表头一样，只不过多一个步骤就是通过head头指针循环找到终端结点
插入结点(1≤i≤ListLength(L))
思路：插入方法与插入到表头一样，多循环查找当前结点的动作
删除结点
思路：同插入结点一样
查找结点
思路：与插入结点和删除结点方法类似
获取链表长度
思路：不像顺序表是连续存储的，获取表的长度非常容易。在链表中，数据不是连续存储的，因此需要循环遍历才能求得链表的长度
PHP链表示意代码&lt;?php
// $Id:$
//链表节点
class node { public $id; //节点id public $name; //节点名称 public $next; //下一节点 public function __construct($id, $name) { $this-&gt;id = $id; $this-&gt;name = $name; $this-&gt;next = null; }
}
//单链表
class singelLinkList { private $header; //链表头节点 //构造方法 public function __construct($id = null, $name = null) { $this-&gt;header = new node($id, $name, null); } //获取链表长度 public function getLinkLength() { $i = 0; $current = $this-&gt;header; while ($current-&gt;next != null) { $i++; $current = $current-&gt;next; } return $i; } //添加节点数据 public function addLink($node) { $current = $this-&gt;header; while ($current-&gt;next != null) { if ($current-&gt;next-&gt;id &gt; $node-&gt;id) { break; } $current = $current-&gt;next; } $node-&gt;next = $current-&gt;next; $current-&gt;next = $node; } //删除链表节点 public function delLink($id) { $current = $this-&gt;header; $flag = false; while ($current-&gt;next != null) { if ($current-&gt;next-&gt;id == $id) { $flag = true; break; } $current = $current-&gt;next; } if ($flag) { $current-&gt;next = $current-&gt;next-&gt;next; } else { echo "未找到id=" . $id . "的节点！&lt;br&gt;"; } } //获取链表 public function getLinkList() { $current = $this-&gt;header; if ($current-&gt;next == null) { echo ("链表为空!"); return; } while ($current-&gt;next != null) { echo 'id:' . $current-&gt;next-&gt;id . ' name:' . $current-&gt;next-&gt;name . "&lt;br&gt;"; if ($current-&gt;next-&gt;next == null) { break; } $current = $current-&gt;next; } } //获取节点名字 public function getLinkNameById($id) { $current = $this-&gt;header; if ($current-&gt;next == null) { echo "链表为空!"; return; } while ($current-&gt;next != null) { if ($current-&gt;id == $id) { break; } $current = $current-&gt;next; } return $current-&gt;name; } //更新节点名称 public function updateLink($id, $name) { $current = $this-&gt;header; if ($current-&gt;next == null) { echo "链表为空!"; return; } while ($current-&gt;next != null) { if ($current-&gt;id == $id) { break; } $current = $current-&gt;next; } return $current-&gt;name = $name; }
}
$lists = new singelLinkList();
$lists-&gt;addLink(new node(5, 'eeeeee'));
$lists-&gt;addLink(new node(1, 'aaaaaa'));
$lists-&gt;addLink(new node(6, 'ffffff'));
$lists-&gt;addLink(new node(4, 'dddddd'));
$lists-&gt;addLink(new node(3, 'cccccc'));
$lists-&gt;addLink(new node(2, 'bbbbbb'));
$lists-&gt;getLinkList();
echo "&lt;br&gt;-----------删除节点--------------&lt;br&gt;";
$lists-&gt;delLink(5);
$lists-&gt;getLinkList();
echo "&lt;br&gt;-----------更新节点名称--------------&lt;br&gt;";
$lists-&gt;updateLink(3, "222222");
$lists-&gt;getLinkList();
echo "&lt;br&gt;-----------获取节点名称--------------&lt;br&gt;";
echo $lists-&gt;getLinkNameById(5);
echo "&lt;br&gt;-----------获取链表长度--------------&lt;br&gt;";
echo $lists-&gt;getLinkLength();
