数算的笔记/互联网开发/数据结构之线性表之顺序表及php代码实现.html.description:
什么是线性表 线性表就是关系中的一对一的关系，如果是一对多就用树来表示，如果多对多就用网状来表示。 简单表示 one&lt;--&gt;two&lt;--&gt;three&lt;--&gt;four 特征(理论，可忽略)： 有且只有一个“首”元素
有且只有一个“尾”元素
除"首"元素外，其余元素都有唯一的后继元素。
除"尾"元素外，其余元素都有唯一的前驱元素。 线性表的两种存储结构 顺序表，即线性表用顺序存储结构保存数据，数据是连续的。
链表，即线性表用链式存储结构保存数据，数据不连续。 顺序表的常见操作顺序表主要有以下常见操作，我们一般用数组来保存数据
初始化
思路：将数组的长度length设为0
求顺序表的长度
思路：获取数组的length值
插入元素
思路：分两种情况，一种是插入位置在数组的末尾，这种情况与添加元素相同。另一种情况是插入位置在数组的开始，这时候被插入元素的后续元素都要依次向后移动一位，也就是说整个数组都会移动
删除元素
思路：同样分两种情况，一种是删除位置在数组的末尾，不用移动任何元素，因此时间复杂度为O(1);另一种情况是删除位置在数组的开始，这时被删除元素的后续元素都要依次向前移动一位
按序号查找元素
思路：因为顺序表的存储地址是连续的，所以第n个元素的地址公式为：(n-1)*单元存储长度，不用移动任何元素
按关键字查找元素
PHP版线性表代码实现注： 在PHP中线性表一个数组就能实现相应功能，理论知识大于实用性，看下面这段PHP版线性表实现&lt;?php
/* *文件名：linearList.php * 功能：数据结构线性表的顺序存储实现 * author:黎锦焕 * @copyright:www.drw1314.com
*/
class linearList { private $arr; private $length; const MAXSIZE = 100; /* *构造函数，判断空表还是飞空表，并且进行实例化 * @param array $arr 输入的数组 * @param int $n 输入数组的长度 * @ruturn void; */ function __construct($arr, $n) { if ($n &gt; self::MAXSIZE) { echo '对不起，数组的长度' . $n . '超出了内存空间!' . self::MAXSIZE; } else if ($n &lt; 0) { echo '异常，长度不能为负数。'; } else if ($n == 0) { echo '&lt;br/&gt;....你创建了一张空表，数组长度为0....&lt;br/&gt;&lt;br/&gt;'; $this-&gt;arr = $arr; $this-&gt;length = $n; } else { echo '&lt;br/&gt;....成功创建一张表....&lt;br/&gt;&lt;br/&gt;'; $this-&gt;arr = $arr; $this-&gt;length = $n; } } /* *按位查找，返回查找到的值 * @ruturn string; * @param int $n 查找的位置 */ function findValue($n) { if ($n &gt; $this-&gt;length || $n &lt; 1) { return '输入的位置' . $n . '不正确，请在1到' . $this-&gt;length . '的范围内'; } return '你要找的第' . $n . '位的值为' . $this-&gt;arr[$n - 1]; } /* *按值查找，返回查找到的位置 * @ruturn string; * @param int $n 查找的值 */ function findSite($n) { for ($i = 0; $i &lt; $this-&gt;length; $i++) { if ($this-&gt;arr[$i] == $n) { $b = $i + 1; return '你要找的值' . $n . '对应的位置为' . $b; } else { $v = false; } } if (!$v) { return '你所找的值' . $n . '不存在'; } } /* *在选定的位置处插入某个值 * @ruturn array; * @param int $i 插入位置 * @param int $v 插入的值 */ function insertValue($i, $v) { if ($i &lt; 1 || $i &gt; self::MAXSIZE) { echo '插入的位置' . $i . '不正确，请在1到' . self::MAXSIZE . '的范围内'; return; } for ($h = $this-&gt;length; $h &gt;= $i; $h--) { $this-&gt;arr[$h] = $this-&gt;arr[$h - 1]; } if ($i &gt; $this-&gt;length) { $this-&gt;arr[$this-&gt;length] = $v; } else { $this-&gt;arr[$i - 1] = $v; } $this-&gt;length++; return $this-&gt;arr; } /* *在选定的位置删除某个值 * @ruturn array; * @param int $i 位置 */ function deleteValue($i) { if ($i &lt; 1 || $i &gt; $this-&gt;length) { echo '选定的位置' . $i . '不正确，请在1到' . $this-&gt;length . '的范围内'; return; } for ($j = $i; $j &lt; $this-&gt;length; $j++) { $this-&gt;arr[$j - 1] = $this-&gt;arr[$j]; } unset($this-&gt;arr[$this-&gt;length - 1]); $this-&gt;length--; return $this-&gt;arr; } function __destruct() { if ($this-&gt;length == 0) { echo '&lt;br/&gt;...销毁一张空表...&lt;br/&gt;'; } else { echo '&lt;br/&gt;...成功销毁一张表..&lt;br/&gt;'; } }
}
//下面是使用案例
$arr = array( 10, 125, 123, 1, 4
);
$n = 5;
$linearList = new linearList($arr, $n);
echo $linearList-&gt;findValue(5) . '&lt;br/&gt;';
echo $linearList-&gt;findSite(4) . '&lt;br/&gt;';
echo '&lt;pre&gt;';
print_r($linearList-&gt;insertValue(20, 300));
echo '&lt;/pre&gt;';
echo '&lt;pre&gt;';
print_r($linearList-&gt;deleteValue(1));
