/** * pdos PDO静态调用支持类 * * 支持insert delete update select query * * //简单使用PDO查询，并返回所有结果 * $a = pdos::select('test_blog')-&gt;where(array('user_id'=&gt;2))-&gt;exec()-&gt;getAll(); * * //删除,并返回是否执行成功 * $b = pdos::delete('test_blog')-&gt;where(array('user_id'=&gt;1))-&gt;exec()-&gt;isTrue(); * * //插入 * $pdo = pdos::insert('test_blog',array('user_id'=&gt;1,'blog'=&gt;'内容2'))-&gt;exec(); * $c = $pdo-&gt;insertId();//获取插入ID * * //更新,不返回有效使用 * $pdo = pdos::update('test_blog',array('blog'=&gt;'blog值'))-&gt;where(array('user_id'=&gt;2))-&gt;exec(); * $d = $pdo-&gt;updateNum();//获取受影响行数 * * //PDO复杂查询使用方法 * $pdo = pdos::select('test_blog b','u.user_id,u.user_name,b.blog_id,b.blog') * -&gt;join('test_user u')-&gt;on(array('b.user_id'=&gt;'u.user_id')) * -&gt;where(array('u.user_id'=&gt;'IN 1,2,3','b.blog_id'=&gt;'&gt;= 158','u.user_name'=&gt;'LIKE a')) * -&gt;group('u.user_id')-&gt;order('b.blog_id DESC')-&gt;limit(0,5); * * $pdo-&gt;exec(); //执行并返回当前PDO封装对象 * $e = $pdo-&gt;getSql(); //获取预处理SQL * $f = $pdo-&gt;getArr();//获取预处理数组 * $g = $pdo-&gt;getOne(); //获取第一行第一列 * $h = $pdo-&gt;getRow(); //获取第一行 * $i = $pdo-&gt;getAll(); //获取所有行 * $j = $pdo-&gt;selectNum();//获取结果集的数目 * * //使用自定义预处理SQL查询(SQL与上面链式操作一样) * $sql = 'SELECT u.user_id,u.user_name,b.blog_id,b.blog FROM test_blog b * LEFT JOIN test_user u ON b.user_id = u.user_id * WHERE u.user_id IN (?, ?, ?) AND b.blog_id &gt;= ? AND u.user_name LIKE ? * GROUP BY u.user_id ORDER BY b.blog_id DESC LIMIT ?,?'; * $k = pdos::query($sql, array(1, 2, 3, 158, 'a', 0, 5))-&gt;getAll(); * * //事务： * $pdo = pdos::insert('test_blog',array('user_id'=&gt;2,'blog'=&gt;'内容2')); * $pdo-&gt;begin(); * $m = $pdo-&gt;exec()-&gt;isTrue(); * $m ? $pdo-&gt;commit() : $pdo-&gt;rollback(); * * var_dump($a,$b,$c,$d,$e,$f,$g,$h,$i,$j,$k,$m); * * @version 1.0 * @author &lt;cd&gt;chendong@yolo24.com * @createtime 2016-06-24 * */
class pdos
{ /** * 增删改查静态入口 * * @version 1.0 2016-06-28 * @author chendong@yolo24.com */ static public function __callStatic($func, $param) { $database = array('select'=&gt;1, 'insert'=&gt;0, 'delete'=&gt;0, 'update'=&gt;0, 'query'=&gt;0); if(isset($database[$func])) { $pdo = new PDO_LIB($database[$func]); return call_user_func_array(array(&amp;$pdo, $func), $param); } else { return false; } }
} /** * PDO_LIB PDO封装库 * * 1,需要database.php有统一配置 * 2,支持多服务器 * 3,支持读写分离 * *一般使用配置database.php： * array( * 'db_type' =&gt; 'mysql', // 数据库类型 * 'db_host' =&gt; '10.126.53.37',// 数据库服务器地址 * 'db_name' =&gt; 'gome_wap', // 数据库名 * 'db_user' =&gt; 'root', // 数据库用户名 * 'db_pwd' =&gt; 'root', // 数据库密码 * 'db_port' =&gt; '7308', // 数据库端口 * 'db_prefix' =&gt; 'wap_', // 数据库表前缀 //因表名配置不统一,暂时不起作用 * ); * * 多台数据库服务器使用配置： * array( * $database1, * $database2, * $database3, * ...... * ) * * 主从使用配置: * array( * //主服务器组 * ayyay( * $database1, * ...... * ), * //从服务器组 * array( * $database3, * ...... * ) * ) * * 4,资源单例连接 * 5,支持链式操作 * 6,支持事务 * 7,除了query操作原生SQL，全部使用预处理 * 8,除了增删改查，支持联表查询 * 9,支持查询中使用&gt; &lt; != = &gt;= &lt;= IN LIKE * 10,支持group * 11,有限度的支持OR * @version 1.0 * @author &lt;cd&gt;chendong@yolo24.com * @createtime 2016-06-27 */
class PDO_LIB
{ static private $_pdos; static private $_pre = ''; private $_pdo; private $_stmt; private $_config; private $_open_rw; private $_sql = ''; private $_data = array(); private $_isTrue = false; private $_result = false; //实例化PDO public function __construct($is_main = 0) { $this-&gt;config(); $is_main = $this-&gt;_open_rw ? $is_main : 0; if (!isset(self::$_pdos[$is_main])) { $num = count($this-&gt;_config[$is_main]); $index = mt_rand(0, $num-1); $config = $this-&gt;_config[$is_main][$index]; $dsn = $config['db_type'] .':host='.$config['db_host'].';port='.$config['db_port'].';dbname='.$config['db_name'].';charset=utf8'; $opts = array( //PDO::ATTR_ERRMODE =&gt; PDO::ERRMODE_EXCEPTION,//设置抛出错误 PDO::ATTR_AUTOCOMMIT =&gt; 1, //开启自动提交 PDO::ATTR_TIMEOUT =&gt; 60, //设置超时时间 PDO::ATTR_PERSISTENT =&gt; false, //持久连接;虽然非常高效,但容易引起问题：表锁、事物阻塞、闲置连接无限循环,故不开启 PDO::MYSQL_ATTR_USE_BUFFERED_QUERY =&gt; true, //开启mysql缓冲查询，使用多重查询结果很重要 PDO::ATTR_EMULATE_PREPARES =&gt; false, //不开启本地预处理，交给mysql转义，防止5.4以下部分版本bug PDO::MYSQL_ATTR_INIT_COMMAND =&gt; 'set names utf8' , //设置提交及结果字符集编码，同时防止部分php版本对dsn设置不完全生效 PDO::ATTR_DEFAULT_FETCH_MODE =&gt; PDO::FETCH_ASSOC, //设置fetchAll结果集为关联索引数组 ); self::$_pdos[$is_main] = new PDO_GOME($dsn, $config['db_user'], $config['db_pwd'], $opts); //前缀不统一,暂不启用 //if (!empty($config['db_prefix'])) //{ // self::$_pre = $config['db_prefix']; //} } $this-&gt;_pdo = &amp; self::$_pdos[$is_main]; } /** * 组合数据库配置 */ private function config() { $this-&gt;_open_rw = false; if (isset($config[0])) { if (isset($config[0][0])) { $this-&gt;_config = $config; $this-&gt;_open_rw = true; //开启主从,读写分离 } else { $this-&gt;_config = array($config,$config); } } else { $config = Config::get('database'); $this-&gt;_config = array(array($config), array($config)); } } public function begin() { return $this-&gt;_pdo-&gt;beginTransaction(); } public function commit() { return $this-&gt;_pdo-&gt;commit(); } public function rollback() { return $this-&gt;_pdo-&gt;rollback(); } /** * 增加一条记录 * str $table 表名 * arr $param array('字段名1'=&gt;'字段值1', '字段名2'=&gt;'字段值2'); * @version 1.0 2016-06-24 * @author chendong@yolo24.com */ public function insert($table = '', $param = array()) { $this-&gt;_sql .= 'INSERT INTO '. self::$_pre . $table .' ('; $values = 'VALUES ('; foreach ($param as $key =&gt; $val) { $this-&gt;_sql .= '`'.$key . '`, '; $values .= '?, '; $this-&gt;_data[] = $val; } $this-&gt;_sql = rtrim($this-&gt;_sql, ', ') . ') ' . rtrim($values, ', ') . ');'; return $this; } /** * 删除记录 * $table 表名 * @version 1.0 2016-06-24 * @author chendong@yolo24.com */ public function delete($table = '') { $this-&gt;_sql .= 'DELETE FROM '. self::$_pre . $table . ' '; return $this; } /** * 更新记录 * str $table 表名 * arr $param array('字段名1'=&gt;'字段值1', '字段名2'=&gt;'字段值2'); * @version 1.0 2016-06-24 * @author chendong@yolo24.com */ public function update($table = '', $param = array()) { $this-&gt;_sql .= 'UPDATE '. self::$_pre . $table .' SET '; foreach ($param as $key =&gt; $val) { $this-&gt;_sql .= '`' . $key . '` = ?, '; $this-&gt;_data[] = $val; } $this-&gt;_sql = rtrim($this-&gt;_sql, ', ') . ' '; return $this; } /** * 查询 * str $table 表名 * mixed $param array('字段名1', '字段名2') | '字段名,字段名' | 不传默认*; * @version 1.0 2016-06-24 * @author chendong@yolo24.com */ public function select($table = '', $param = array()) { $this-&gt;_sql .= 'SELECT '; if (is_string($param)) { $this-&gt;_sql .= $param .' '; } elseif (empty($param)) { $this-&gt;_sql .= '* '; } else { $this-&gt;_sql .= implode(',', $param) . ' '; } $this-&gt;_sql .= 'FROM '. self::$_pre . $table .' '; return $this; } /** * 使用自定义预处理SQL * @version 1.0 2016-06-27 * @author chendong@yolo24.com */ public function query($sql, $param) { $this-&gt;_sql = $sql; $this-&gt;_data = $param; return $this-&gt;exec(); } /** * order by * str $by '字段名 DESC' | '字段名 ASC' * @version 1.0 2016-06-27 * @author chendong@yolo24.com */ public function where($param = array()) { $this-&gt;_sql .= 'WHERE '; if($param) { foreach ($param as $key =&gt; $val) { $this-&gt;whereStr($key, $val); $this-&gt;_sql .= 'AND '; } $this-&gt;_sql = rtrim($this-&gt;_sql, 'AND ') .' '; } else { $this-&gt;_sql .= '1 '; } return $this; } /** * order by * str $by '字段名 DESC' | '字段名 ASC' * @version 1.0 2016-06-27 * @author chendong@yolo24.com */ public function andOr($param = array()) { if($param) { $this-&gt;_sql .= 'AND ( '; foreach ($param as $key =&gt; $val) { $this-&gt;whereStr($key, $val); $this-&gt;_sql .= 'OR '; } $this-&gt;_sql = rtrim($this-&gt;_sql, 'OR ') .' ) '; } return $this; } /** * 支持 != = &gt; &lt; IN LIKE &gt;= &lt;= * @version 1.0 2016-06-27 * @author chendong@yolo24.com */ private function whereStr($key, $val) { $arr = array('&gt;', '&lt;', '!', '='); $first = strtoupper(substr($val,0,1)); if(in_array($first, $arr) || strtoupper(substr($val,0,3)) == 'IN ' || strtoupper(substr($val,0,5)) == 'LIKE ') { $index = strpos($val, ' '); $this-&gt;_sql .= $key .' '.substr($val, 0, $index).' '; $value = substr($val, ++$index); if($first == 'I') { $this-&gt;_sql .= '('; $arr = explode(',', $value); foreach ($arr as $k =&gt; $v) { $this-&gt;_sql .= '?, '; $this-&gt;_data[] = $v; } $this-&gt;_sql = rtrim($this-&gt;_sql, ', ') .') '; } else { $this-&gt;_sql .= '? '; $this-&gt;_data[] = $value; } } else { $this-&gt;_sql .= $key .' = ? '; $this-&gt;_data[] = $val; } } /** * group by * str $by '字段名' * @version 1.0 2016-06-27 * @author chendong@yolo24.com */ public function group($by) { $this-&gt;_sql .= 'GROUP BY '. $by .' '; return $this; } /** * order by * str $by '字段名 DESC' | '字段名 ASC' * @version 1.0 2016-06-27 * @author chendong@yolo24.com */ public function order($by) { $this-&gt;_sql .= 'ORDER BY '. $by .' '; return $this; } /** * limit * @version 1.0 2016-06-27 * @author chendong@yolo24.com */ public function limit($start, $num) { $this-&gt;_sql .= 'LIMIT ?,? '; $this-&gt;_data[] = $start; $this-&gt;_data[] = $num; return $this; } /** * join * @version 1.0 2016-06-27 * @author chendong@yolo24.com */ public function join($table='', $param = array(), $place = 'LEFT') { $this-&gt;_sql .= $place .' JOIN '. self::$_pre . $table .' ON '; if($param) { foreach($param as $key=&gt;$val) { $this-&gt;whereStr($key, $val); $this-&gt;_sql .= 'AND '; } $this-&gt;_sql = rtrim($this-&gt;_sql, 'AND ') .' '; } return $this; } /** * join * @version 1.0 2016-06-27 * @author chendong@yolo24.com */ public function on($param = array()) { if($param) { foreach ($param as $key =&gt; $val) { $this-&gt;_sql .= $key .' = '. $val .' AND '; } $this-&gt;_sql = rtrim($this-&gt;_sql, 'AND ') .' '; } return $this; } /** * 执行sql * @version 1.0 2016-06-27 * @author chendong@yolo24.com */ public function exec() { try { $this-&gt;_stmt = $this-&gt;_pdo-&gt;prepare($this-&gt;_sql); $this-&gt;_isTrue = $this-&gt;_stmt ? $this-&gt;_stmt-&gt;execute($this-&gt;_data) : false; } catch (PDOException $e) { $this-&gt;log('query error : ' . $e-&gt;getMessage()); $this-&gt;_isTrue = false; } return $this; } /** * 输出上一次执行是否成功 * @version 1.0 2016-06-28 * @author chendong@yolo24.com */ public function isTrue() { return $this-&gt;_isTrue; } /** * 返回上一条insert的SQL的自增id * @version 1.0 2016-06-27 * @author chendong@yolo24.com */ public function insertId() { return $this-&gt;_isTrue ? intval($this-&gt;_pdo-&gt;lastInsertId()) : 0; } /** * 返回上一条SQL的影响行数 * @version 1.0 2016-06-27 * @author chendong@yolo24.com */ public function updateNum() { return $this-&gt;_isTrue ? intval($this-&gt;_stmt-&gt;rowCount()) : 0; } /** * 结果集总数 * @version 1.0 2016-06-24 * @author chendong@yolo24.com */ public function selectNum() { return $this-&gt;_isTrue ? $this-&gt;_pdo-&gt;query("SELECT FOUND_ROWS()")-&gt;fetchColumn() : 0; } /** * 返回select的一行结果集 * @version 1.0 2016-06-27 * @author chendong@yolo24.com */ public function getRow() { $result = $this-&gt;getAll(); $result = $result ? $result[0] : false; return $result; } /** * 返回select的所有结果集 * @version 1.0 2016-06-27 * @author chendong@yolo24.com */ public function getAll() { if (empty($this-&gt;_result) &amp;&amp; $this-&gt;_isTrue &amp;&amp; strtoupper(substr($this-&gt;_sql, 0, 6) == 'SELECT')) { $this-&gt;_result = $this-&gt;_stmt-&gt;fetchAll(); } return $this-&gt;_result; } /** * 按sql获取第一条数据的第一列到值 * @version 1.0 2016-06-27 * @author chendong@yolo24.com */ public function getOne() { $result = $this-&gt;getRow(); $result = $result ? reset($result) : false; return $result; } /** * 输出SQL * @version 1.0 2016-06-28 * @author chendong@yolo24.com */ public function getSql() { return $this-&gt;_sql; } /** * 输出预处理的数组 * @version 1.0 2016-06-28 * @author chendong@yolo24.com */ public function getArr() { return $this-&gt;_data; } /** * 记录日志 * @version 1.0 2016-06-27 * @author chendong@yolo24.com */ function log($str) { file_put_contents(LOG_PATH . '/pdo_error.log', date('Y-m-d H:i:s').' '.$str . "\n", FILE_APPEND); }
} /** * PDO_GOME PDO类重载优化 * 1,优化两次开启事务 * 2,防止暴露连接信息 * * @version 1.0 * @author &lt;cd&gt;chendong@yolo24.com * @createtime 2016-06-24 */
class PDO_GOME extends PDO
{ private $transactionCounter = 0; //防止两次开启事务报错 public function __construct($dsn, $user='', $pwd='', $opts=array()) { //暂时改变php的异常处理，防止暴露连接信息 set_exception_handler(array(__CLASS__, 'exception_handler')); parent::__construct($dsn, $user, $pwd, $opts); restore_exception_handler(); } public static function exception_handler($e) { $error = $e-&gt;getMessage(); file_put_contents(LOG_PATH . '/pdo_error.log', date('Y-m-d H:i:s').' '.$error . "\n", FILE_APPEND); exit('ERROR:'.$error); } function beginTransaction() { if (!$this-&gt;transactionCounter++) { return parent::beginTransaction(); } return $this-&gt;transactionCounter &gt;= 0; } function commit() { if (!--$this-&gt;transactionCounter) { return parent::commit(); } return $this-&gt;transactionCounter &gt;= 0; } function rollback() { if ($this-&gt;transactionCounter &gt;= 0) { $this-&gt;transactionCounter = 0; return parent::rollback(); } $this-&gt;transactionCounter = 0; return false; }
}

数算的笔记/互联网开发/php素数判定算法.html.description:
素数定义
除了能被1和它本身整除而不能被其他任何数整除的数 直接根据定义计算素数
根据素数定义 只需要用2到n-1去除n，如果都除不尽，则n是素数，否则，只要其中有一个数能整除则n不是素数
&lt;?php
function is_prime($num) { for ($i = 2; $i &lt; $num; $i++) { if ($num % $i == 0) { return false; } } return true;
}
